assert.deepEqual(mergeConfig({ n: { x: 1 } }, { n: null }), { n: null });
// nested override replaces primitive default
assert.deepEqual(mergeConfig({ n: 5 }, { n: { x: 1 } }), { n: { x: 1 } });
// primitive override replaces nested default
assert.deepEqual(mergeConfig({ n: { x: 1 } }, { n: 5 }), { n: 5 });

// inherited keys ignored
