const out3 = mergeConfig({ n: JSON.parse('{"__proto__": {"x": 1}}') }, {});
assert.deepEqual(Object.keys(out3.n), ['__proto__']);
assert.equal(Object.getPrototypeOf(out3.n), Object.prototype);

// repeated calls with same defaults independent
const shared = { n: { x: 1 } };
const a1 = mergeConfig(shared, { n: { y: 1 } });
const a2 = mergeConfig(shared, { n: { z: 1 } });
assert.deepEqual(a1, { n: { x: 1, y: 1 } });
assert.deepEqual(a2, { n: { x: 1, z: 1 } });
assert.deepEqual(shared, { n: { x: 1 } });

// null prototype plain object accepted
const np = Object.create(null);
np.k = 1;
assert.deepEqual(mergeConfig(np, {}), { k: 1 });

console.log('all checks passed');
